KG42.register("rules-1e54b009e2ea19c189e0b6b6",{"id":"05-double_auction::v141-c-R020","paper":"05-double_auction","record":{"rule_id":"v141-c-R020","mechanism_id":"v141-a-M04","name":"Local market coordinator","process_stage":"coordination","market_meaning":"The difference between the trading buyer's payment and the trading seller's receipt may accrue to the market operator as financial gain from each single-unit transaction. Scope: TR single-unit transactions in the local P2P energy market. Condition: $B_{\\gamma}^P \\geq S_{\\gamma}^P$","independence_rationale":"Relations governed by the approved function coordination.local_operator under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["coordination.local_operator","settlement.payment"],"E":[{"edge_id":"v141-c-R020-E001","source":"settlement.payment","target":"coordination.local_operator","type":"links","constraint_ids":["v141-c-R020-C001"],"evidence_ids":["v141-b-g01-ev-08"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"TR single-unit transactions in the local P2P energy market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-08"]},"x":[],"theta":[{"parameter_id":"v141-c-R020-theta-BgammaP","symbol":"B_{\\gamma}^P","meaning":"Bid price of buyer gamma, the marginal breakeven buyer excluded from trading in the Trade Reduction auction.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/kWh","indices":["\\gamma"],"evidence_ids":["v141-b-g01-ev-06","v141-b-g01-ev-08"]},{"parameter_id":"v141-c-R020-theta-SgammaP","symbol":"S_{\\gamma}^P","meaning":"Ask price of seller gamma, the marginal breakeven seller excluded from trading in the Trade Reduction auction.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/kWh","indices":["\\gamma"],"evidence_ids":["v141-b-g01-ev-06","v141-b-g01-ev-08"]}],"phi":[{"constraint_id":"v141-c-R020-C001","kind":"procedural","role":"core","statement":"The difference between the trading buyer's payment and the trading seller's receipt may accrue to the market operator as financial gain from each single-unit transaction. Scope: TR single-unit transactions in the local P2P energy market. Condition: $B_{\\gamma}^P \\geq S_{\\gamma}^P$","expression":"B_{\\gamma}^P - S_{\\gamma}^P \\quad \\text{given } B_{\\gamma}^P \\geq S_{\\gamma}^P","formalization_origin":"source","template_id":null,"members":["settlement.payment","coordination.local_operator"],"variable_refs":[],"parameter_refs":["v141-c-R020-theta-BgammaP","v141-c-R020-theta-SgammaP"],"evidence_ids":["v141-b-g01-ev-08","v141-b-g01-ev-06"]}],"pi":[{"evidence_id":"v141-b-g01-ev-08","location":{"location_id":"src-22913ad574-p03-c1r2__v141-a-M04-clearing","page":3,"printed_page":null,"section":"2.1","anchor_text":"of trades while maintaining truthful bidding by limiting trades to 1 Ta buyers and sellers [45]. Suc","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The Trade Reduction (TR) auction mechanism avoids subsidization of trades while maintaining truthful bidding by limiting trades to $\\gamma - 1$ buyers and sellers [45]. Such differs from uniform k-DA and VCG, where $\\gamma$ buyers and sellers are allowed to transact. Because buyer $\\gamma$ and seller $\\gamma$ are not permitted to participate in the TR auction, social welfare is not maximized. However, trading buyers pay $B_{\\gamma}^P$ and trading sellers receive $S_{\\gamma}^P$. As $B_{\\gamma}^P \\geq S_{\\gamma}^P$, the market operator may financially gain $B_{\\gamma}^P - S_{\\gamma}^P$ from each single unit transaction."},{"evidence_id":"v141-b-g01-ev-06","location":{"location_id":"src-22913ad574-p02-c2r4__v141-a-M04-pricing","page":2,"printed_page":null,"section":"2.1","anchor_text":"a y g g p s- does not exist for each auction interval. of Uniform k-DA is a variation to discriminat","equation_id":null,"figure_id":null,"table_id":"Table 1","image_ref":"pages/page-02.png","occurrence_role":"formula"},"source_text":"Table 1 Auction mechanisms. TR | Price trading buyers pay: $B_{\\gamma}^P$ | Price trading sellers receive: $S_{\\gamma}^P$"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":"The rule does not introduce any design selection or operational decision variable. The operator's financial gain is determined by the given participant bid/ask prices (parameters B_gamma^P and S_gamma^P) and the Trade Reduction mechanism's exclusion of the marginal pair; the market operator does not select a value for this gain.","empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M04-clearing","v141-a-M04-pricing"],"extras":{"decision_anchor":"coordination.local_operator","graph_fact_supports":[[{"evidence_id":"v141-b-g01-ev-08","quote":"However, trading buyers pay $B_{\\gamma}^P$ and trading sellers receive $S_{\\gamma}^P$. As $B_{\\gamma}^P \\geq S_{\\gamma}^P$, the market operator may financially gain $B_{\\gamma}^P - S_{\\gamma}^P$ from each single unit transaction."}]],"C2_formalization":{"graph_sha256":"debbe4458edf44533f7243fb5400c2efe11840bc4d4ef0d1efe004ac0ecb417e","applicability":"formalized","reason":"The source explicitly states that the market operator may financially gain B_gamma^P - S_gamma^P from each single-unit transaction under the condition B_gamma^P >= S_gamma^P. This is a supported mathematical relation between the buyer payment (settlement.payment) and the operator's financial position (coordination.local_operator).","bindings":[{"object_id":"v141-c-R020-theta-BgammaP","node_ids":["settlement.payment"],"edge_ids":["v141-c-R020-E001"],"rationale":"B_gamma^P is the payment made by the trading buyer gamma, which is part of settlement.payment and determines, together with S_gamma^P, the financial gain flowing to coordination.local_operator via the linking edge v141-c-R020-E001."},{"object_id":"v141-c-R020-theta-SgammaP","node_ids":["settlement.payment"],"edge_ids":["v141-c-R020-E001"],"rationale":"S_gamma^P is the receipt of the trading seller gamma, part of settlement.payment; the difference B_gamma^P - S_gamma^P accrues to coordination.local_operator through the edge v141-c-R020-E001."},{"object_id":"v141-c-R020-C001","node_ids":["settlement.payment","coordination.local_operator"],"edge_ids":["v141-c-R020-E001"],"rationale":"The constraint states that the difference between the buyer payment and seller receipt in settlement.payment may become financial gain for coordination.local_operator; the edge v141-c-R020-E001 links these nodes with type 'links' and carries this constraint."}],"revision_requests":[]},"C2_delivery":{"raw_sha256":"a8616f51befaa193cd7d4c3ca98290b0ffc8e8b1eda11746c551bb444a99c2a4","delivery_payload_sha256":"c8613ec69739abf527c0e410535ab2a42801f5b035703e9fb0c3a4a45f6b82f8","changes":[{"path":"theta.0.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.1.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"debbe4458edf44533f7243fb5400c2efe11840bc4d4ef0d1efe004ac0ecb417e","scientific_correctness_verified":false}},"quarantined_references":[]}});
